#!/usr/bin/env python3
"""
Round 111b (culprits), 29 September 2026. Needs round 110b.

ForestAtRisk's probability of deforestation 2020 (shown with Cirad's
permission), and the notes for the fire and fertility rows after the failed
refresh of 29 September. Tiles patch round111b_tiles.py beside it.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

DIFF = ''

NOTE = '## Round 111b (29 September)\n\nNeeds round 110b. Tiles patch round111b_tiles.py beside it. Made alongside the\nother chat\'s 110c to 112c; touches none of their rows. Leaves app.js?v= as it\nis, so the other chat\'s next bump is not in the way.\n\n- ForestAtRisk (Cirad, EC JRC), probability of deforestation 2020: Cirad\n  answered on 29 September that it is "in principle happy to support\n  non-commercial educational use of the prob_2020 map". Row forestatrisk\n  (route rasterparts) leads Deforestation > Tree cover loss and alerts > Where\n  clearing is likely; ten equal steps of probability, teal to cobalt. Built by\n  tiles scripts/forestatrisk.py from the three 30 m COGs on\n  forestatrisk.cirad.fr/tropics/tif/ (prob_2020_{AME,AFR,ASI}_aea.tif, values\n  1 + p x 65534), warped to zoom 9 (about 300 m; FAR_MAXZOOM=10 for 150 m).\n  addRasterPartsLayer now takes cfg.stateSay.\n- Refresh of 29 September, nine failures, fixed in tiles: aqueduct (crop table\n  paged through GFW\'s query), atlas_insets (count vs list), fertility_policy\n  (2019 fertility file; multi-row headings), fish_rivers ("Layer:" lines),\n  ftw_overview (list-type=2; it looped on page one), ifl (authors\'\n  GeoPackages first; GFW "latest" is 404), inpe_fire (two builds joined, 84\n  MB), public_harm (IMF unpack), slavery_world (UNODC\'s new portal; CBP 403\n  no longer fails the run). Notes for inpe_fire_2023 and fertility_policy say\n  what changed.\n- Read after that refresh: fur/farms.geojson has 778 farms (Final Nail 270,\n  Farm Transparency 335, OSM 265 less overlaps), Final Nail\'s own map fields\n  kept as "Final Nail: ..."; spam/build.json has no licence text (readme {});\n  probe/nusantara/health.json: 18 Nusantara layers draw nothing at zooms 2 to\n  8 (finance, refineries, Papua, Merauke, Rawa Singkil, sago, 10 km buffer);\n  probe/crime: ILAT is a Tableau view, TRAFFIC\'s portal a script page, no\n  files; probe/enforcement not yet mapped.\n\n'
HEAD = '## Round 111b (29 September)'


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round111b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    text = h.read_text(encoding="utf-8")
    if "## Round 110b" not in text:
        sys.exit("round111b: round 110b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round111b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            sys.exit("round111b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round111b: applied")
    text = h.read_text(encoding="utf-8")
    if HEAD not in text:
        at = text.index("## Round ")
        h.write_text(text[:at] + NOTE + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
